# v1: deliberate draft chain (no random picks), Treasure strength shards plus Power health shards,
# retreat early when in danger and hurt, and tribute at altars away from monolith rings when possible.

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_heart_of_ruin()):
        pick(champ_heart_of_ruin())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    else:
        pick(random_champion(pool))
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
keep monster_ring = ring(monolith_tiles(), 5)

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains(spawn_region(ally()), position())
if at_spawn:
    let shards_bought = floor(gold() / 30)
    let str_shards = floor(shards_bought / 2)
    buy(shard_of(family_treasure(), stat_strength()), str_shards)
    buy(shard(stat_health()), shards_bought - str_shards)
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# retreat: 20% health normally; earlier when an enemy can hit us, or when carrying gems
let threatened = in_danger()
if not at_spawn and (health() < 0.2 * max_health() or (threatened and health() < 0.4 * max_health()) or (gems() > 0 and health() < 0.5 * max_health())):
    recall()
    end_turn()

let enemy = first(filter(enemies_visible(), in_attack_range()))
if exists(enemy):
    if ability_ready(0):
        cast_at_unit(0, enemy)
    if ability_ready(1):
        cast_at_unit(1, enemy)
    attack(enemy)
    end_turn()

if gems() > 0:
    let open_altars = minus(altars(), locked_altars())
    let safe_altars = minus(open_altars, monster_ring)
    let altar = first(filter(open_altars, within(1, position())))
    if exists(altar):
        tribute(altar)
        end_turn()
    let dest = closest(ring(safe_altars, 1))
    if exists(dest):
        move_towards(dest)
    else:
        move_towards(closest(ring(open_altars, 1)))
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first(filter(camps, in_attack_range()))
if exists(camp):
    if ability_ready(0):
        cast_at_unit(0, camp)
    if ability_ready(1):
        cast_at_unit(1, camp)
    attack(camp)
    end_turn()

let goals = minus(camp_spawns, respawning_visible_spawns())

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(goals, position()):
    end_turn()

move_towards(closest(goals))
let camp2 = first(filter(camps, in_attack_range()))
if exists(camp2):
    attack(camp2)
set_priority(1 + random_int(100))
end_turn()

# v1: v0 plus a fixed draft chain, gem-camp preference, altars away from monoliths,
# retreat from losing local fights, and recall at 35% health (50% when carrying gems).

# ---- draft: fixed pick order ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_heart_of_ruin()):
        pick(champ_heart_of_ruin())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_stellar()):
        pick(champ_stellar())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let strength_shards = floor( shards_bought / 2 )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), shards_bought - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# retreat: 35% health normally, 50% when carrying gems
if not at_spawn and (health() < 0.35 * max_health() or (gems() > 0 and health() < 0.5 * max_health())):
    recall()
    end_turn()

let enemy = first( filter( enemies_visible(), in_attack_range() ) )
if exists(enemy):
    # losing local fight: step away instead of trading
    if not at_spawn and local_strength(5) < 0.7 and enemies_within(5) > allies_within(5):
        move_away_from( unit_position(enemy) )
        end_turn()
    if ability_ready(0):
        cast_at_unit(0, enemy)
    if ability_ready(1):
        cast_at_unit(1, enemy)
    attack(enemy)
    end_turn()

if gems() > 0:
    let open_altars = minus( altars(), locked_altars() )
    # prefer altars outside monolith range
    let safe_altars = minus( open_altars, ring( monolith_tiles(), 5 ) )
    let altar = first( filter( open_altars, within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    let safe_ring = ring( safe_altars, 1 )
    let st = closest( safe_ring )
    if exists(st):
        move_towards(st)
        end_turn()
    let ot = closest( ring(open_altars, 1) )
    if exists(ot):
        move_towards(ot)
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    if ability_ready(0):
        cast_at_unit(0, camp)
    if ability_ready(1):
        cast_at_unit(1, camp)
    attack(camp)
    end_turn()

let goals = minus( camp_spawns, respawning_visible_spawns() )

# hold on a cleared camp spawn so the capture timer keeps running
if contains(goals, position()):
    end_turn()

# prefer gem clusters (gems win games), otherwise any camp
let gem_goals = minus( gem_cluster_tiles(), respawning_visible_spawns() )
let gem_target = closest( gem_goals )
if exists(gem_target):
    move_towards( gem_target )
else:
    move_towards( closest(goals) )

let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

